parameters.functionCode:
// Determine which SMS to send based on day number and lead behavior
const items = $input.all();
const smsMessages = [];

items.forEach(item => {
  const lead = item.json;
  const dayNumber = lead.day_number;
  let message = '';
  let messageType = '';

  // Day-specific messages
  switch(dayNumber) {
    case 1:
      messageType = 'welcome';
      message = `Hi ${lead.first_name}! Thanks for starting your mortgage journey with us. Your dedicated loan officer will call you today. Got questions? Reply YES to connect now.`;
      break;
    case 2:
      messageType = 'document-reminder';
      message = `${lead.first_name}, here's a quick tip: Having your documents ready speeds up approval! Check your email for the full checklist. Reply DOCS for a direct link.`;
      break;
    case 3:
      messageType = 'rate-update';
      message = `Good news ${lead.first_name}! Today's rates are competitive. Want to lock in? Reply LOCK or call us at ${process.env.OFFICE_PHONE}.`;
      break;
    case 5:
      messageType = 'milestone';
      message = `${lead.first_name}, you're 5 days into your mortgage journey! 🏠 Most approvals happen within 14 days. Need help moving faster? Reply HELP.`;
      break;
    case 7:
      messageType = 'weekly-checkin';
      message = `Happy 1-week anniversary ${lead.first_name}! Let's get you approved this week. What's your biggest question right now? Just reply and we'll answer.`;
      break;
    case 10:
      messageType = 'education';
      message = `${lead.first_name}, did you know: Pre-approval increases your buying power by 20%? Ready to get pre-approved? Reply PREAPPROVE.`;
      break;
    case 14:
      messageType = 'two-week-milestone';
      message = `2 weeks in! ${lead.first_name}, you're halfway through the average approval timeline. What can we do to help you close faster? Reply or call ${process.env.OFFICE_PHONE}.`;
      break;
    case 21:
      messageType = 'urgency';
      message = `${lead.first_name}, rates fluctuate daily. Lock in your rate before they rise! Reply LOCK or schedule a call: ${process.env.BOOKING_LINK}`;
      break;
    case 30:
      messageType = 'final-touchpoint';
      message = `${lead.first_name}, it's been a month! We're still here to help you get approved. Last chance for our current rate specials. Reply YES to reconnect.`;
      break;
    default:
      if (dayNumber % 7 === 0) {
        messageType = 'weekly-checkin';
        message = `Hi ${lead.first_name}, just checking in! How can we help you move forward with your mortgage? Reply with your questions.`;
      }
  }

  if (message) {
    smsMessages.push({
      json: {
        leadId: lead.id,
        firstName: lead.first_name,
        phone: lead.phone,
        email: lead.email,
        dayNumber: dayNumber,
        messageType: messageType,
        message: message,
        leadScore: lead.lead_score
      }
    });
  }
});

return smsMessages;

// Parse incoming SMS response
const response = $input.item.json;

const keywords = {
  'YES': 'callback_requested',
  'LOCK': 'rate_lock_requested',
  'DOCS': 'documents_requested',
  'HELP': 'assistance_requested',
  'PREAPPROVE': 'preapproval_requested',
  'STOP': 'unsubscribe'
};

const messageBody = (response.Body || response.body || '').toUpperCase().trim();
const fromNumber = response.From || response.from;

let intent = 'general_inquiry';
for (const [keyword, action] of Object.entries(keywords)) {
  if (messageBody.includes(keyword)) {
    intent = action;
    break;
  }
}

return {
  json: {
    from: fromNumber,
    message: messageBody,
    intent: intent,
    timestamp: new Date().toISOString()
  }
};

